void dfs(int u, int p, int d) {
    depth_parity[u] = d % 2;
    cnt_parity[d % 2]++;
    for (int i = 0; i < deg[u]; i++) {
        int v = edges[u][i];
        if (v != p) {
            dfs(v, u, d + 1);
        }
    }
