        edges[a] = realloc(edges[a], sizeof(int) * (deg[a] + 1));
        edges[b] = realloc(edges[b], sizeof(int) * (deg[b] + 1));
        edges[a][deg[a]++] = b;
        edges[b][deg[b]++] = a;
    }

