    int cnt1 = (N + 2) / 3;
    int cnt2 = (N + 1) / 3;

    int p0 = cnt_parity[0];
    int p1 = cnt_parity[1];

    int assign[N+1];
    memset(assign, 0, sizeof(assign));

    int possible = 0;

    // Try put 1's on parity0, 2's on parity1
    if (p0 >= cnt1 && p1 >= cnt2 && (p0 - cnt1) + (p1 - cnt2) >= cnt0) {
        int idx1 = 1, idx2 = 2, idx0 = 3;
