                    idx2 += 3;
                    cnt2--;
                } else {
                    assign[i] = idx0;
                    idx0 += 3;
                    cnt0--;
                }
            }
        }
        possible = 1;
    }

    // Try put 1's on parity1, 2's on parity0
    if (!possible && p1 >= cnt1 && p0 >= cnt2 && (p1 - cnt1) + (p0 - cnt2) >= cnt0) {
        int idx1 = 1, idx2 = 2, idx0 = 3;
        for (int i = 1; i <= N; i++) {
