static int *color;
static int cnt[2];

static int *group0, *group1;
static int gsz[3], gcap[3];
static int *grp[3];

static void add_edge(int u, int v) {
    E[ecnt].to = v;
    E[ecnt].next = head[u];
    head[u] = ecnt++;
}

static void dfs_color(int start) {
    int *stack = (int*)malloc((N + 5) * sizeof(int));
    int top = 0;
    stack[top++] = start;
    color[start] = 0;
    cnt[0] = 1;
    cnt[1] = 0;

    while (top) {
        int u = stack[--top];
        for (int e = head[u]; e != -1; e = E[e].next) {
            int v = E[e].to;
            if (color[v] == -1) {
                color[v] = color[u] ^ 1;
                cnt[color[v]]++;
                stack[top++] = v;
            }
        }
    }
    free(stack);
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    head = (int*)malloc((N + 1) * sizeof(int));
