        if (color[i] == 0) group0[p0++] = i;
        else group1[p1++] = i;
    }

    for (int r = 0; r < 3; r++) {
        gcap[r] = N / 3 + 5;
        grp[r] = (int*)malloc(gcap[r] * sizeof(int));
        gsz[r] = 0;
    }

    for (int x = 1; x <= N; x++) {
        int r = x % 3;
        grp[r][gsz[r]++] = x;
    }

    int *ans = (int*)malloc((N + 1) * sizeof(int));

    int small = cnt[0] < cnt[1] ? 0 : 1;
    int big = small ^ 1;

    if (cnt[small] <= gsz[0]) {
        int idx0 = 0, idx1 = 0, idx2 = 0;
        int ps = 0, pb = 0;

        if (small == 0) {
            for (int i = 0; i < cnt[0]; i++) ans[group0[ps++]] = grp[0][idx0++];
            for (int i = 0; i < cnt[1]; i++) {
                if (idx1 < gsz[1]) ans[group1[pb++]] = grp[1][idx1++];
                else ans[group1[pb++]] = grp[2][idx2++];
            }
        } else {
            for (int i = 0; i < cnt[1]; i++) ans[group1[ps++]] = grp[0][idx0++];
            for (int i = 0; i < cnt[0]; i++) {
                if (idx1 < gsz[1]) ans[group0[pb++]] = grp[1][idx1++];
                else ans[group0[pb++]] = grp[2][idx2++];
            }
        }
    } else {
        int idx0 = 0, idx1 = 0, idx2 = 0;
        int psmall = 0, pbig = 0;

        for (int i = 0; i < cnt[0]; i++) {
            if (idx1 < gsz[1]) ans[group0[psmall++]] = grp[1][idx1++];
            else ans[group0[psmall++]] = grp[2][idx2++];
        }
        for (int i = 0; i < cnt[1]; i++) {
            if (idx1 < gsz[1]) ans[group1[pbig++]] = grp[1][idx1++];
            else ans[group1[pbig++]] = grp[2][idx2++];
        }

        idx1 = idx2 = 0;
        psmall = pbig = 0;

        /* Rebuild properly: one part gets residues 1 and 2, the other gets residue 0 plus leftovers.
           Standard construction:
           - Put all multiples of 3 into one color class if possible.
           - Otherwise assign by residue classes arbitrarily within each color class.
           Since cnt[small] > gsz[0], both classes need non-zero residues only works if we do:
             color 0 gets residues 1 then 2
             color 1 gets residues 0 then remaining 1/2
           or vice versa.
        */
        if (cnt[0] <= gsz[1] + gsz[2]) {
            idx0 = idx1 = idx2 = 0;
            int t0 = 0, t1 = 0;
            for (int i = 0; i < cnt[0]; i++) {
                if (idx1 < gsz[1]) ans[group0[t0++]] = grp[1][idx1++];
                else ans[group0[t0++]] = grp[2][idx2++];
            }
            for (int i = 0; i < cnt[1]; i++) {
                if (idx0 < gsz[0]) ans[group1[t1++]] = grp[0][idx0++];
                else if (idx1 < gsz[1]) ans[group1[t1++]] = grp[1][idx1++];
                else ans[group1[t1++]] = grp[2][idx2++];
            }
        } else {
            idx0 = idx1 = idx2 = 0;
            int t0 = 0, t1 = 0;
            for (int i = 0; i < cnt[1]; i++) {
                if (idx1 < gsz[1]) ans[group1[t1++]] = grp[1][idx1++];
