#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    // Bipartite coloring of the tree
    vector<int> color(N + 1, -1);
    vector<int> part[2];
    queue<int> q;
    color[1] = 0;
    q.push(1);
    part[0].push_back(1);

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int to : g[v]) {
            if (color[to] == -1) {
                color[to] = color[v] ^ 1;
                part[color[to]].push_back(to);
                q.push(to);
            }
        }
    }

    int c0 = (int)part[0].size();
    int c1 = (int)part[1].size();

    vector<int> ans(N + 1, 0);

    // Numbers by residue mod 3
    vector<int> r0, r1, r2;
    for (int x = 1; x <= N; ++x) {
        if (x % 3 == 0) r0.push_back(x);
        else if (x % 3 == 1) r1.push_back(x);
        else r2.push_back(x);
    }

    // Key observation:
    // Vertices at distance 3 are in opposite bipartition classes.
    // To guarantee condition for every such pair, it is enough to assign
    // one side numbers all divisible by 3, or assign one side only residues 1
    // and the other side only residues 2 (or vice versa).
    //
    // Standard constructive strategy:
    // 1) If one side size <= count(multiples of 3), put all multiples of 3 there.
    // 2) Otherwise, since both sides are > floor(N/3), one side can fit in residues 1,
    //    the other in residues 2 after using multiples of 3 as fillers.

    if (c0 <= (int)r0.size()) {
        // Put multiples of 3 on part 0
        int i0 = 0, i1 = 0, i2 = 0;
        for (int v : part[0]) ans[v] = r0[i0++];
        for (int v : part[1]) {
            if (i1 < (int)r1.size()) ans[v] = r1[i1++];
            else ans[v] = r2[i2++];
        }
    } else if (c1 <= (int)r0.size()) {
        // Put multiples of 3 on part 1
        int i0 = 0, i1 = 0, i2 = 0;
        for (int v : part[1]) ans[v] = r0[i0++];
        for (int v : part[0]) {
            if (i1 < (int)r1.size()) ans[v] = r1[i1++];
            else ans[v] = r2[i2++];
        }
    } else {
        // Neither side fits entirely in multiples of 3.
        // Then assign:
        // smaller side -> one nonzero residue class as much as possible
        // remaining vertices -> the other nonzero residue class
        // leftover positions on each side can be filled with multiples of 3.
        //
        // This ensures every cross-part pair has either sum divisible by 3
        // (1 with 2) or product divisible by 3 (if one endpoint gets residue 0).
        int i0 = 0, i1 = 0, i2 = 0;

        if (c0 <= (int)r1.size()) {
            for (int v : part[0]) ans[v] = r1[i1++];
            for (int v : part[1]) {
                if (i2 < (int)r2.size()) ans[v] = r2[i2++];
                else ans[v] = r0[i0++];
            }
        } else if (c1 <= (int)r1.size()) {
            for (int v : part[1]) ans[v] = r1[i1++];
            for (int v : part[0]) {
                if (i2 < (int)r2.size()) ans[v] = r2[i2++];
                else ans[v] = r0[i0++];
            }
        } else if (c0 <= (int)r2.size()) {
            for (int v : part[0]) ans[v] = r2[i2++];
            for (int v : part[1]) {
                if (i1 < (int)r1.size()) ans[v] = r1[i1++];
                else ans[v] = r0[i0++];
            }
        } else {
            for (int v : part[1]) ans[v] = r2[i2++];
            for (int v : part[0]) {
                if (i1 < (int)r1.size()) ans[v] = r1[i1++];
                else ans[v] = r0[i0++];
            }
        }
    }

    for (int i = 1; i <= N; ++i) {
        if (i > 1) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';

    return 0;
}

