        }

        // Step 3: Assign values
        int[] result = new int[N + 1];
        int count1 = 0, count2 = 0, count0 = 0;
        List<Integer> side0 = new ArrayList<>();
        List<Integer> side1 = new ArrayList<>();

        for (int i = 1; i <= N; i++) {
            if (dist3Color[i] == 0) side0.add(i);
            else side1.add(i);
        }

        // Assign: side0 gets 1, side1 gets 2 (or vice versa), fill rest with 0s
        // We have N numbers from 1 to N, need exactly N/3 of each residue if N multiple of 3

        int limit0 = N / 3;
        int limit1 = N / 3;
        int limit2 = N - limit0 - limit1;

        int[] assign = new int[N + 1];

        // Assign 1s and 2s to opposite sides
        for (int idx : side0) {
            if (count1 < limit1) {
                assign[idx] = 1;
                count1++;
            } else if (count2 < limit2) {
                assign[idx] = 2;
                count2++;
            } else {
                assign[idx] = 0;
                count0++;
            }
        }

        for (int idx : side1) {
            if (count2 < limit2) {
                assign[idx] = 2;
                count2++;
            } else if (count1 < limit1) {
                assign[idx] = 1;
                count1++;
            } else {
                assign[idx] = 0;
                count0++;
            }
        }

        // Fill remaining with 0s wherever possible
        for (int i = 1; i <= N; i++) {
            if (assign[i] == 0 && count0 < limit0) {
                assign[i] = 0;
                count0++;
            } else if (assign[i] == 0) {
                // assign 1 or 2 if still needed
                if (count1 < limit1) {
                    assign[i] = 1;
                    count1++;
                } else {
                    assign[i] = 2;
                    count2++;
                }
            }
        }

        // Map values 1..N to residues
        int[] valueMap = new int[N + 1];
        List<Integer>[] byRes = new ArrayList[3];
        for (int i = 0; i < 3; i++) byRes[i] = new ArrayList<>();
        for (int i = 1; i <= N; i++) {
            byRes[assign[i]].add(i);
        }

        int[] numbers = new int[N + 1];
        int cur0 = 3, cur1 = 1, cur2 = 2;
        for (int i = 1; i <= N; i++) {
            int r = assign[i];
            if (r == 0) {
                numbers[i] = cur0;
                cur0 += 3;
            } else if (r == 1) {
                numbers[i] = cur1;
                cur1 += 3;
            } else {
                numbers[i] = cur2;
                cur2 += 3;
            }
        }

        // Output
        for (int i = 1; i <= N; i++) {
            System.out.print(numbers[i] + (i == N ? "\n" : " "));
        }
    }

    static boolean bfsColor(int start, List<Integer>[] adj) {
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        dist3Color[start] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (dist3Color[v] == -1) {
                    dist3Color[v] = 1 - dist3Color[u];
                    q.add(v);
                } else if (dist3Color[v] == dist3Color[u]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int[] color;
    static ArrayList<Integer> part0 = new ArrayList<>();
    static ArrayList<Integer> part1 = new ArrayList<>();

    static void bfsColor() {
        Arrays.fill(color, -1);
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        color[1] = 0;
        dq.add(1);

        while (!dq.isEmpty()) {
            int v = dq.poll();
            if (color[v] == 0) part0.add(v);
            else part1.add(v);

            for (int to : g[v]) {
                if (color[to] == -1) {
                    color[to] = color[v] ^ 1;
                    dq.add(to);
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            g[a].add(b);
            g[b].add(a);
        }

        color = new int[N + 1];
        bfsColor();

        ArrayList<Integer> mod0 = new ArrayList<>();
        ArrayList<Integer> mod1 = new ArrayList<>();
        ArrayList<Integer> mod2 = new ArrayList<>();

        for (int x = 1; x <= N; x++) {
            int r = x % 3;
            if (r == 0) mod0.add(x);
            else if (r == 1) mod1.add(x);
            else mod2.add(x);
        }

        int[] ans = new int[N + 1];

        // Key observation:
        // In a tree, vertices at distance 3 always belong to opposite bipartition sides.
        // So if we assign one whole side numbers divisible by 3,
        // then for every pair at distance 3, one endpoint is divisible by 3,
        // hence product is divisible by 3.
        //
        // If one side has size <= count(multiples of 3), we can do it directly.
        int c0 = part0.size();
        int c1 = part1.size();
        int m0 = mod0.size();

        StringBuilder out = new StringBuilder();

        if (c0 <= m0 || c1 <= m0) {
            ArrayList<Integer> special = (c0 <= m0) ? part0 : part1;
            boolean[] isSpecial = new boolean[N + 1];
            for (int v : special) isSpecial[v] = true;

            int p0 = 0, p1 = 0, p2 = 0;
            for (int v = 1; v <= N; v++) {
                if (isSpecial[v]) {
                    ans[v] = mod0.get(p0++);
                }
            }
            for (int v = 1; v <= N; v++) {
                if (!isSpecial[v]) {
                    if (p1 < mod1.size()) ans[v] = mod1.get(p1++);
                    else ans[v] = mod2.get(p2++);
                }
            }

            for (int i = 1; i <= N; i++) {
                if (i > 1) out.append(' ');
                out.append(ans[i]);
            }
            System.out.println(out);
            return;
        }

        // Otherwise, both sides have more than floor(N/3) vertices.
        // Then one side can be filled with numbers congruent to 1 mod 3,
        // the other with numbers congruent to 2 mod 3, and leftover multiples of 3 anywhere.
        // For any pair at distance 3 (opposite sides), residues are 1 and 2 or one is 0.
        // Then sum is 0 mod 3 in the 1/2 case, or product is 0 mod 3 if one is 0.
        //
        // This construction works when each side fits into count(mod1)+count(mod0) or count(mod2)+count(mod0),
        // and with both sides > m0, we can assign the smaller side to the smaller nonzero class if needed.

        ArrayList<Integer> A = part0, B = part1;
        if (A.size() > B.size()) {
            ArrayList<Integer> tmp = A;
            A = B;
            B = tmp;
        }

        // Assign A mostly from mod1, B mostly from mod2, use mod0 as overflow.
        int p0 = 0, p1 = 0, p2 = 0;

        for (int v : A) {
            if (p1 < mod1.size()) ans[v] = mod1.get(p1++);
            else ans[v] = mod0.get(p0++);
        }
        for (int v : B) {
            if (p2 < mod2.size()) ans[v] = mod2.get(p2++);
            else ans[v] = mod0.get(p0++);
        }

        for (int i = 1; i <= N; i++) {
            if (i > 1) out.append(' ');
            out.append(ans[i]);
        }
        System.out.println(out);
    }
}

